//! Tag parsing and track assembly against the fixtures generated by `fixtures/generate.sh`.

#![expect(clippy::unwrap_used, reason = "tests")]

use std::path::PathBuf;

use localify_core::color::{CoverAccent, DEFAULT_ACCENT, cover_accent};
use localify_core::source::{ChunkedReader, Counting, FileSource};
use localify_core::tags::{Tags, read_tags};
use localify_core::track::parse_track;

const TITLE: &str = "Fixture Tïtle ✓";

fn path(name: &str) -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("tests/fixtures")
        .join(name)
}

fn bytes(name: &str) -> Vec<u8> {
    std::fs::read(path(name)).unwrap()
}

fn tags(name: &str) -> Tags {
    let ext = name.rsplit_once('.').unwrap().1;
    read_tags(
        ChunkedReader::new(FileSource::open(path(name)).unwrap()),
        ext,
    )
    .unwrap()
}

fn assert_text(tags: &Tags) {
    assert_eq!(tags.title.as_deref(), Some(TITLE));
    assert_eq!(tags.artist.as_deref(), Some("Fixture Artist"));
    assert_eq!(tags.album.as_deref(), Some("Fixture Album"));
}

fn assert_cover(tags: &Tags, cover: &str, mime: &str) {
    let picture = tags.picture.as_ref().expect("a cover");
    assert_eq!(picture.data, bytes(cover));
    assert_eq!(picture.mime, mime);
}

#[test]
fn mp3_id3v23() {
    let t = tags("id3v23.mp3");
    assert_text(&t);
    assert_cover(&t, "cover.png", "image/png");
}

#[test]
fn mp3_id3v24() {
    let t = tags("id3v24.mp3");
    assert_text(&t);
    assert_cover(&t, "cover.png", "image/png");
}

#[test]
fn flac() {
    let t = tags("tagged.flac");
    assert_text(&t);
    assert_cover(&t, "cover.jpg", "image/jpeg");
}

#[test]
fn m4a() {
    let t = tags("tagged.m4a");
    assert_text(&t);
    assert_cover(&t, "cover.jpg", "image/jpeg");
}

#[test]
fn ogg_vorbis() {
    let t = tags("tagged.ogg");
    assert_text(&t);
    assert_cover(&t, "cover.png", "image/png");
}

#[test]
fn opus() {
    let t = tags("tagged.opus");
    assert_text(&t);
    assert_cover(&t, "cover.jpg", "image/jpeg");
}

#[test]
fn opus_cover_spanning_ogg_pages() {
    let t = tags("big-cover.opus");
    assert_text(&t);
    // A 130 × 130 noise PNG of 50 913 bytes, 67 940 bytes as base64: more than one Ogg page holds.
    let picture = t.picture.expect("a cover");
    assert_eq!(picture.mime, "image/png");
    assert_eq!(picture.data.len(), 50_913);
    assert!(picture.data.starts_with(b"\x89PNG\r\n\x1a\n"));
    assert!(picture.data.ends_with(b"IEND\xae\x42\x60\x82"));
    assert!(matches!(
        cover_accent(&picture.data, &picture.mime, 0.0),
        CoverAccent::Decoded(Some(_))
    ));
}

#[test]
fn wav_riff_info() {
    let t = tags("tagged.wav");
    assert_text(&t);
    assert_eq!(t.picture, None);
}

#[test]
fn untagged() {
    assert_eq!(tags("untagged.mp3"), Tags::default());
}

#[test]
fn artist_list_stands_in_for_a_missing_artist() {
    let t = tags("artists.flac");
    assert_eq!(t.title.as_deref(), Some("Fixture Title"));
    assert_eq!(t.artist.as_deref(), Some("Alice, Bob & Carol"));
}

#[test]
fn content_wins_over_extension() {
    let file = FileSource::open(path("tagged.flac")).unwrap();
    let t = read_tags(ChunkedReader::new(file), "mp3").unwrap();
    assert_text(&t);
}

#[test]
fn truncated_and_garbage_input_never_panics() {
    let names = [
        "id3v23.mp3",
        "id3v24.mp3",
        "tagged.flac",
        "tagged.m4a",
        "tagged.ogg",
        "tagged.opus",
        "big-cover.opus",
        "tagged.wav",
    ];
    for name in names {
        let data = bytes(name);
        let ext = name.rsplit_once('.').unwrap().1;
        let mut cut = 0;
        while cut < data.len() {
            let _ = read_tags(ChunkedReader::new(&data[..cut]), ext);
            let track = parse_track(name, &data[..cut], None::<&[u8]>, 0.5);
            assert!(!track.title.is_empty());
            cut += if cut < 256 { 1 } else { 97 };
        }
        // Flip bytes throughout the file.
        for step in [7, 31, 255] {
            let mut bad = data.clone();
            for i in (0..bad.len()).step_by(step) {
                bad[i] ^= 0x5a;
            }
            let _ = parse_track(name, &bad[..], None::<&[u8]>, 0.5);
        }
    }
    for ext in ["mp3", "flac", "m4a", "ogg", "opus", "wav", ""] {
        let garbage: Vec<u8> = (0..4096u32).map(|i| (i * 7919 % 251) as u8).collect();
        // Without reading audio properties, lofty accepts an MPEG stream it finds no tags in.
        let result = read_tags(ChunkedReader::new(&garbage[..]), ext);
        assert!(
            result.as_ref().is_err() || result.as_ref().is_ok_and(|t| *t == Tags::default()),
            "{ext}: {result:?}"
        );
    }
}

#[test]
fn track_with_decoded_covers() {
    let png = parse_track(
        "x.mp3",
        FileSource::open(path("id3v23.mp3")).unwrap(),
        Some(FileSource::open(path("cover.png")).unwrap()),
        0.0,
    );
    assert_eq!(png.title, TITLE);
    assert_eq!(png.format, "mp3");
    // ffmpeg's colour conversion turned #d02040 into #cf1f3f.
    assert_eq!(png.accent, [0xcf, 0x1f, 0x3f]);
    assert!(!png.cover_undecoded);
    assert_eq!(png.error, None);
    // The lyrics source is read whole and decoded lossily.
    assert!(png.lyrics.unwrap().contains("PNG"));

    let jpeg = parse_track(
        "x.FLAC",
        FileSource::open(path("tagged.flac")).unwrap(),
        None::<FileSource>,
        0.0,
    );
    assert_eq!(jpeg.format, "flac");
    // JPEG is lossy: the solid #2060e0 comes back approximately.
    let [r, g, b] = jpeg.accent;
    assert!(
        r.abs_diff(0x20) < 8 && g.abs_diff(0x60) < 8 && b.abs_diff(0xe0) < 8,
        "{:?}",
        jpeg.accent
    );
    assert!(!jpeg.cover_undecoded);
    assert_eq!(jpeg.lyrics, None);
}

#[test]
fn untagged_track_falls_back() {
    let t = parse_track(
        "Some Song.mp3",
        FileSource::open(path("untagged.mp3")).unwrap(),
        None::<FileSource>,
        0.0,
    );
    assert_eq!(t.title, "Some Song");
    assert_eq!(t.artist, "Unknown Artist");
    assert_eq!(t.album, "");
    assert_eq!(t.accent, DEFAULT_ACCENT);
    assert_eq!(t.cover, None);
    assert_eq!(t.error, None);
}

#[test]
fn multi_page_cover_costs_few_range_reads() {
    let mut source = Counting::new(FileSource::open(path("big-cover.opus")).unwrap());
    let t = parse_track("big-cover.opus", &mut source, None::<FileSource>, 0.0);
    assert!(t.cover.is_some());
    assert!(source.reads() <= 4, "{} reads", source.reads());
}
